import numpy as np, time
# eigvals only (no vectors) - cheaper?
for sz in [2,4,6,8,10]:
    A=np.random.normal(size=(sz,sz))
    for _ in range(5): np.linalg.eigvals(A)
    ts=[]
    for _ in range(2000):
        t=time.perf_counter(); np.linalg.eigvals(A); ts.append(time.perf_counter()-t)
    print('eigvals',sz, np.median(ts)*1e6, 'us')
# eigh (symmetric) for reference
for sz in [2,4,6,8,10]:
    A=np.random.normal(size=(sz,sz))
    for _ in range(5): np.linalg.eigh(A)
    ts=[]
    for _ in range(2000):
        t=time.perf_counter(); np.linalg.eigh(A); ts.append(time.perf_counter()-t)
