import numpy as np
from numpy.linalg._umath_linalg import eig
# Test: what if A is a 0-d or scalar?
try:
    eig(np.array(5.0))
except Exception as e:
    print('0d ERR', type(e).__name__, str(e)[:80])
# Test: 3D stack (np.linalg.eig supports stacks)
