    r=eig(A); print('stack OK', r[0].shape, r[1].shape)
except Exception as e:
    print('stack ERR', type(e).__name__, str(e)[:80])
# np.linalg.eig on stack
try:
    w,v=np.linalg.eig(A); print('np stack OK', w.shape)
